P = [
 dict(pmid='43014176', doi='10.1016/j.jhazmat.2026.144174', journal='J Hazard Mater', title='Aerosol-radiation interactions reshape cross-mountain dust transport and downwind air quality responses over a mountain-basin system.', short='Sichuan Basin December 2018 dust intrusion WRF-Chem aerosol-radiation interaction cross-mountain PM10 ozone', design='Chemical-transport modelling', pm='PM10 and ozone from multi-source observations and online-coupled WRF-Chem with/without ARI', geo='China (Sichuan Basin)', endpoint='Cross-mountain PM10 flux, near-surface PM10, boundary-layer height', tier='C', basis='Model (CTM / LUR / ML)', affil='Sichuan University, China; Sichuan University, China', n='One dust intrusion into the Sichuan Basin (2-5 December 2018) analysed with observations, Lagrangian dispersion and WRF-Chem with and without aerosol-radiation interactions. Dust crossed the Qinling-Daba mountains on elevated pathways, raising PM10 and ozone. ARI cut maximum boundary-layer height by 17.5% over the plateau and 28.7% in the basin, lowered cumulative cross-mountain PM10 transport by 13.6% and near-surface basin PM10 by 23.5 ug/m3 (about 10%); ozone rose 8.2 ppbv. A single event and a single model configuration; the ARI effect depends on the dust optical properties assumed. Relevance: indirect - forecasts that omit ARI overpredict basin PM10 during dust events, which matters when they are used to flag sensor outliers.', sub=corpus.EXPO),
 dict(pmid='43013885', doi='10.1080/15459624.2026.2749875', journal='J Occup Environ Hyg', title='Titanium dioxide exposure in the Western Australian mining industry: Implications for compliance with current and proposed exposure limits.', short='Western Australia mining TiO2 604 personal inhalable samples 2018-2025 proposed ultrafine fine exposure limits', design='Monitoring-record analysis', pm="Personal inhalable TiO2 samples from the state regulator's database", geo='Australia (Western Australia)', endpoint='Exceedance of current (10 mg/m3) and proposed (0.3, 2.4 mg/m3) TiO2 limits', tier='C', basis='Personal / wearable', affil='Edith Cowan University, Australia; Edith Cowan University, Australia', n="De-identified regulator data: 604 personal inhalable TiO2 samples from Western Australian mining, 2018-2025, compared with the current 10 mg/m3 inhalable limit and proposed limits of 0.3 mg/m3 (ultrafine/nanoscale) and 2.4 mg/m3 (fine, respirable). Exposures were consistently low; one sample exceeded the numerical value of the proposed ultrafine limit and the second highest was 0.12 mg/m3; none exceeded 2.4 mg/m3; trends were stable or falling. The weakness is the conclusion itself: inhalable gravimetric mass says nothing about the ultrafine/nanoscale fraction the 0.3 mg/m3 limit targets, so 'conservative evidence of compliance' does not follow for that limit. Relevance: peripheral - illustrates why size-specific limits need size-resolved measurement, not legacy inhalable samples.", sub=corpus.OCC),
 dict(pmid='43011813', doi='10.3389/fpubh.2026.1869182', journal='Front Public Health', title='Associations between air pollution, accelerated biological aging, and oral inflammatory diseases: evidence from the UK Biobank cohort.', short='UK Biobank 348247 PM2.5 PM10 PM2.5-10 absorbance NO2 oral inflammatory disease KDM-BA PhenoAge mediation', design='Prospective cohort', pm='Residential LUR PM2.5, PM10, PM2.5-10, PM2.5 absorbance, NO2, NOx (2010)', geo='UK', endpoint='Incident oral inflammatory diseases; biological-age acceleration as mediator', tier='B', basis='Model (CTM / LUR / ML)', affil='Central Hospital of Wuhan, Huazhong University of Science and Technology, China; Gannan Medical University, China', n='UK Biobank, 348,247 adults, median follow-up 16.49 years, 3,967 incident oral inflammatory diseases. Per SD increment, PM2.5, PM10, PM2.5-10 and PM2.5 absorbance were associated with 8%, 4%, 3% and 5% higher incidence (NO2 10%, NOx 8%; all p<0.05). PhenoAge acceleration mediated 8.52-16.65% of the associations, KDM biological age 1.21-5.42%. The abstract reports no confidence intervals. Exposure is a single-year (2010) land-use regression surface applied over 16 years, the outcome comes from hospital coding of a condition mostly managed in primary dental care, and mediation by a biomarker measured at baseline alongside exposure cannot establish temporal ordering. Relevance: peripheral - modelled exposure, no measurement content.', sub=corpus.OTHR),
 dict(pmid='43011452', doi='10.3389/ftox.2026.1951777', journal='Front Toxicol', title='ExposomeMap-PM: fine and ultrafine particle-induced toxicity - from adverse outcome pathways to systems biomedicine disease models.', short='Luxembourg Institute of Health ExposomeMap-PM disease map 304 entities 497 processes AOP transcriptomic overlay', design='Mechanistic review', pm='Fine and ultrafine particle exposure (knowledge model); one reference particle, 3-day exposure for the overlay', geo='Global / multi-region (review)', endpoint='Mechanistic network coverage; enrichment of differentially expressed genes', tier='B', basis='Review / no primary exposure', affil='Luxembourg Institute of Health, Luxembourg; Luxembourg Institute of Health, Luxembourg', n='A curated mechanistic disease map linking fine and ultrafine particle exposure to outcomes: 304 entities and 497 processes in five blocks (alveolar deposition, oxidative stress, barrier disruption, mitochondrial dysfunction, pro-inflammatory signalling) ending in asthma, COPD, atherosclerosis and neurodegeneration, built in SBGN and served on MINERVA. In a test overlay from one reference particle and a 3-day exposure, map nodes captured 1.50-fold more differentially expressed transcripts than size-matched random gene sets (permutation p=0.0074); proteomics 1.13-fold. One particle type and a short exposure validate coverage, not completeness, and enrichment is partly guaranteed by curating from the same literature. Relevance: indirect - a reusable scaffold for attaching composition-resolved exposure, which low-cost mass sensors do not provide.', sub=corpus.MECH),
]
